import java.io.IOException;
import java.util.*;

public class Test {
    int readInt() {
        int ans = 0;
        boolean neg = false;
        try {
            boolean start = false;
            for (int c = 0; (c = System.in.read()) != -1; ) {
                if (c == '-') {
                    start = true;
                    neg = true;
                    continue;
                } else if (c >= '0' && c <= '9') {
                    start = true;
                    ans = ans * 10 + c - '0';
                } else if (start) break;
            }
        } catch (IOException e) {
        }
        return neg ? -ans : ans;
    }

    int r, c;
    Scanner scanner = new Scanner(System.in);
    long[][] C = new long[64][64];
    long bestDistance = Long.MAX_VALUE;

    void dfsSearch(long x, long y, int v1, int v2) {
        long diff = Math.abs(x - y);
        if (bestDistance <= 1 || diff - C[v1][r]*C[v2][r] >= bestDistance) return;
        if (v1 == r - 1 && v2 == r - 1) {
            if (diff < bestDistance) bestDistance = diff;
            return;
        }
        if (v1 >= r) {
            long deltaX = C[v1][r] - C[v1-1][r], deltaY = C[v2][r];
            dfsSearch(x, y + deltaX*deltaY, v1 - 1, v2);
        }
        if (v2 >= r) {
            long deltaX = C[v1][r], deltaY = C[v2][r] - C[v2-1][r];
            dfsSearch(x + deltaX*deltaY, y, v1, v2 - 1);
        }
    }

    int[] countA = new int[64], countB = new int[64];
    Map<Long, Long> memoCache = new TreeMap<>();
    char[] sequenceChars;

    long recursiveSolve(long x, long y, int v1, int v2) {
        long key = x*10000 + v1*100 + v2;
        Long cachedVal = memoCache.get(key);
        if (cachedVal != null) return cachedVal;
        long result = 0L;
        long d = Math.abs(x - y);
        if (d - C[v1][r]*C[v2][r] > bestDistance) {
            memoCache.put(key, result);
            return result;
        }
        if (v1 < r || v2 < r) {
            int sumIndex = v1 + v2;
            if (v1 >= countA[sumIndex] && v2 >= countB[sumIndex]) {
                v1 -= countA[sumIndex];
                v2 -= countB[sumIndex];
                result = C[v1+v2][v1];
                memoCache.put(key, result);
                return result;
            }
            memoCache.put(key, result);
            return result;
        }
        char c = sequenceChars[v1 + v2 - 1];
        if (c != 'B') {
            long c1 = C[v1][r] - C[v1 - 1][r], s2 = C[v2][r];
            result += recursiveSolve(x, y + c1*s2, v1 - 1, v2);
        }
        if (c != 'A') {
            long s1 = C[v1][r], c2 = C[v2][r] - C[v2-1][r];
            result += recursiveSolve(x + s1*c2, y, v1, v2 - 1);
        }
        memoCache.put(key, result);
        return result;
    }

    void execute() {
        r = scanner.nextInt(); c = scanner.nextInt(); scanner.nextLine();
        sequenceChars = scanner.nextLine().toCharArray();
        for (int i = 0; i <= 2*(r + c); i++)
            for (int j = 0; j <= 2*(r + c); j++) {
                if (j == 0) C[i][j] = 1;
                else if (i == 0) C[i][j] = 0;
                else C[i][j] = C[i-1][j - 1] + C[i - 1][j];
            }
        int v1 = r + c, v2 = r + c;
        long xCoord = 0, yCoord = 0;
        while (v1 >= r && v2 >= r) {
            if (xCoord > yCoord) {
                long c1 = C[v1][r] - C[v1 - 1][r], s2 = C[v2][r];
                yCoord += c1 * s2;
                v1--;
            } else {
                long s1 = C[v1][r], c2 = C[v2][r] - C[v2-1][r];
                xCoord += s1 * c2;
                v2--;
            }
        }
        bestDistance = Math.abs(xCoord - yCoord);
        dfsSearch(0, 0, r + c, r + c);
        for (int i = 0; i < 2*(r+c); i++) {
            countA[i + 1] = countA[i] + (sequenceChars[i] == 'A' ? 1 : 0);
            countB[i + 1] = countB[i] + (sequenceChars[i] == 'B' ? 1 : 0);
        }
        long answer = recursiveSolve(0, 0, r + c, r + c);
        System.out.println(answer);
    }

    public static void main(String[] args) {
        new Test().execute();
    }
}
